mapper.select:
SELECT o.id, o.attr_id, o.name, o.prompt_value, o.sort_order, s.step_number, s.name AS step_name FROM human_prompt_option o INNER JOIN human_prompt_attr a ON a.id = o.attr_id INNER JOIN human_prompt_step s ON s.id = a.step_id WHERE o.id IN
